<?php require '../config/db.php';require '../includes/functions.php';require '../includes/mailer.php';$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL))json_response(false,'Enter your name and a valid email address.',[],422);$q=$pdo->prepare('SELECT id FROM newsletter_subscribers WHERE email=?');$q->execute([$email]);if($q->fetch())json_response(false,'This email is already subscribed.',[],409);$pdo->prepare('INSERT INTO newsletter_subscribers(name,email,status) VALUES(?,?,\'active\')')->execute([$name,$email]);$admin=envv('MAIL_ADMIN_ADDRESS');$a=$admin?send_mail_message($admin,'New newsletter subscriber',"<p>".e($name)." (".e($email).") subscribed.</p>"):false;$b=send_mail_message($email,'Newsletter subscription confirmed',"<h2>Welcome, ".e($name).".</h2><p>Your newsletter subscription is confirmed.</p>");json_response(true,($a&&$b)?'Subscription confirmed. Emails were sent.':'Subscription saved. Configure working mail settings in .env for email delivery.');